   var mat=GameObject.Find("Plan B - Shared Render And Navigation Surface").GetComponent<Renderer>().sharedMaterial;mat.SetTexture("_DetailMask",Bake("ForestFloorMask",colors,true));EditorUtility.SetDirty(mat);a.passed=true;File.WriteAllText(Logs+"/refine.json",JsonUtility.ToJson(a,true));EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();CapturePreview(Camera.main,Find<WarSandboxRuntimeDeployment>(scene).battlefieldCatalog);Review();}
  public static void FinishVisuals(){Require(!File.Exists(Logs+"/layout-final.json"),"Already finalized");var scene=EditorSceneManager.OpenScene(Battle,OpenSceneMode.Single);Require(Find<MassEngineManager>(scene).TryGetTerrainContext(out surface,out _,out var error),error);var back=GameObject.Find("Visual Only Backdrop - No navigation or colliders").GetComponent<MeshFilter>().sharedMesh;var group=GameObject.Find("21 Grouped understory and trail verges").transform;var old=group.Cast<Transform>().Where(t=>t.name.Contains("grassPatch")).ToArray();rng=new System.Random(2107);int added=0;foreach(var source in old)for(int k=0;k<2;k++){var b=BoundsOf(source.gameObject);float angle=Rand(0,6.283f);var p=b.center+new Vector3(Mathf.Cos(angle)*Rand(.9f,2.4f),0,Mathf.Sin(angle)*Rand(.9f,2.4f));var go=Object.Instantiate(source.gameObject,group);go.name="21 clustered grass";go.transform.rotation=Quaternion.Euler(0,Rand(0,360),0);go.transform.localScale*=Rand(.65f,.95f);var nb=BoundsOf(go);float h=Mathf.Max(Mathf.Abs(p.x),Mathf.Abs(p.z))>256?VisualHeight(back,p.x,p.z):TerrainScaleBounds.BackdropHeight(surface,p.x,p.z);go.transform.position+=new Vector3(p.x,h-.06f,p.z)-new Vector3(nb.center.x,nb.min.y,nb.center.z);if(!Clear(BoundsOf(go))){Object.DestroyImmediate(go);continue;}added++;}
   var root=GameObject.Find("21 Artful Woodland - visual only outside navigation");var report=JsonUtility.FromJson<Audit21>(File.ReadAllText(Logs+"/prepare.json"));report.addedProps+=added;report.props=root.transform.Cast<Transform>().Sum(t=>t.childCount);report.renderers=root.GetComponentsInChildren<Renderer>().Length;report.decorationTriangles=root.GetComponentsInChildren<MeshFilter>().Sum(f=>Scene18AssetAudit.Triangles(f.sharedMesh));Require(report.decorationTriangles<380000,"Final budget exceeded");Require(root.GetComponentsInChildren<Collider>(true).Length==0,"Unexpected collisions");foreach(var r in root.GetComponentsInChildren<Renderer>())Require(Clear(r.bounds),"Final bounds intrude");ActorMaterialBuildGuard.RequireValid(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();File.WriteAllText(Logs+"/layout-final.json",JsonUtility.ToJson(report,true));CapturePreview(Camera.main,Find<WarSandboxRuntimeDeployment>(scene).battlefieldCatalog);Review();}
  public static void FinishWood(){Require(!File.Exists(Logs+"/wood-finish.json"),"Wood already done");var scene=EditorSceneManager.OpenScene(Battle,OpenSceneMode.Single);var group=GameObject.Find("Irregular forest floor and trail landmarks").transform;var fences=group.Cast<Transform>().Where(t=>t.name.IndexOf("Fence",StringComparison.OrdinalIgnoreCase)>=0).ToArray();Require(fences.Length==7,"Fence count mismatch");var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name="21 warm timber - intentional solid color";mat.SetColor("_BaseColor",new Color(.28f,.16f,.075f,1));mat.SetFloat("_Smoothness",.04f);mat.enableInstancing=true;AssetDatabase.CreateAsset(mat,Root+"/Materials/WarmTimber.mat");foreach(var f in fences)foreach(var r in f.GetComponentsInChildren<Renderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>mat).ToArray();EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();CapturePreview(Camera.main,Find<WarSandboxRuntimeDeployment>(scene).battlefieldCatalog);Review();File.WriteAllText(Logs+"/wood-finish.json","{\"passed\":true,\"fences\":7,\"intentionalSolidWoodColor\":true}");}
  static void ReviewShot(Camera c,string name){var rt=new RenderTexture(1280,720,24);var t=new Texture2D(1280,720,TextureFormat.RGB24,false);var old=c.targetTexture;var active=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes(Logs+"/"+name+".png",t.EncodeToPNG());}finally{c.targetTexture=old;RenderTexture.active=active;rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(t);}}
  public static void Review(){ShaderUtil.allowAsyncCompilation=false;var s=EditorSceneManager.OpenScene(Battle,OpenSceneMode.Single);var c=Camera.main;c.transform.position=new Vector3(-190,48,-316);c.transform.LookAt(new Vector3(-115,15,-238));ReviewShot(c,"editor-seam");c.transform.position=new Vector3(-276,19,-9);c.transform.LookAt(new Vector3(-307,9,29));ReviewShot(c,"editor-understory");var floor=GameObject.Find("21 Grouped understory and trail verges").transform.Cast<Transform>().Where(t=>t.name.Contains("grassPatch")).OrderBy(t=>(new Vector2(t.position.x,t.position.z)-new Vector2(-272,52)).sqrMagnitude).First();var target=floor.GetComponentInChildren<Renderer>().bounds.center;c.transform.position=target+new Vector3(10,7,-12);c.transform.LookAt(target+Vector3.up);ReviewShot(c,"editor-floor");var materials=GameObject.Find("21 Artful Woodland - visual only outside navigation").GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Concat(new[]{GameObject.Find("Plan B - Shared Render And Navigation Surface").GetComponent<Renderer>().sharedMaterial}).Distinct().ToArray();var tex=materials.SelectMany(m=>m.GetTexturePropertyNames().Select(p=>m.GetTexture(p))).OfType<Texture2D>().Distinct().ToArray();Require(tex.All(t=>t.width<=1024&&t.height<=1024),"Texture max cap exceeded");File.WriteAllText(Logs+"/texture-audit.json",JsonUtility.ToJson(new TextureAudit21{passed=true,materials=materials.Length,textures=tex.Select(t=>new TextureInfo{path=AssetDatabase.GetAssetPath(t),width=t.width,height=t.height,format=t.format.ToString()}).ToArray()},true));}
